  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Human PET imaging with the high-transfer analogue [18F]TRACK demonstrates proven in vivo brain penetration and on-target CNS signal, directly supporting meaningful BBB access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Brain/plasma PK in mice shows good brain exposure for a close analogue, indicating adequate CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "PET studies in pigs show desirable brain uptake and accumulation in relevant brain regions for a high-transfer analogue, supporting CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A rat CSF/plasma AUC ratio of 0.46 for a structurally related molecule demonstrates meaningful unbound brain exposure, consistent with adequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A high-transfer analogue was shown not to be a P-glycoprotein substrate and exhibited rapid brain uptake in rhesus monkey PET imaging, reducing concern about efflux limiting CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Dynamic PET in mice showed excellent brain uptake (7% ID/cc) for a close analogue, providing strong in vivo evidence of BBB permeability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful CNS access across multiple species and assay types, including human PET, rodent brain/plasma PK, CSF/plasma ratio, and efflux-negative PET tracers. The query shares relevant CNS-penetrant features with these analogues, so the prediction is pass.",
  "evidence_gaps": [
    "No direct experimental brain or CSF concentration data are available for the query molecule itself.",
    "The query's specific P-gp/BCRP efflux liability has not been directly measured, though close analogues show no efflux limitation.",
    "Radiotracer brain uptake evidence may not fully recapitulate steady-state unbound therapeutic brain concentrations."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

